import{_ as a,o as s,c as n,a4 as o}from"./chunks/framework.BBs01uty.js";const c=JSON.parse('{"title":"数据分布场景与锁设计（单库 / 主从 / 分片 / 分布式库）","description":"","frontmatter":{},"headers":[],"relativePath":"service/data-distribution-locks.md","filePath":"service/data-distribution-locks.md"}'),e={name:"service/data-distribution-locks.md"};function d(r,t,i,l,p,h){return s(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="数据分布场景与锁设计-单库-主从-分片-分布式库" tabindex="-1">数据分布场景与锁设计（单库 / 主从 / 分片 / 分布式库） <a class="header-anchor" href="#数据分布场景与锁设计-单库-主从-分片-分布式库" aria-label="Permalink to &quot;数据分布场景与锁设计（单库 / 主从 / 分片 / 分布式库）&quot;">​</a></h1><blockquote><p><strong>优先级：P1</strong> — 面试与架构里最容易被绕晕的一组概念：多实例、主从、分库分表、分布式数据库——它们的数据存放方式不同，&quot;锁/一致/并发&quot;的问题也完全不同。本文用一张地基图分清四种形态，逐个讲&quot;数据和锁怎么设计&quot;。</p></blockquote><h2 id="一、地基-数据分布的四种形态-先分清-别混" tabindex="-1">一、地基：数据分布的四种形态（先分清，别混） <a class="header-anchor" href="#一、地基-数据分布的四种形态-先分清-别混" aria-label="Permalink to &quot;一、地基：数据分布的四种形态（先分清，别混）&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 单库（多应用实例共享）  ：一份数据，所有实例连同一个 MySQL</span></span>
<span class="line"><span>② 主从复制 / 读写分离     ：同一份数据&quot;多副本&quot;，主库写、从库读</span></span>
<span class="line"><span>③ 分库分表                ：数据&quot;切片&quot;分散，每个库存一部分（不同数据）</span></span>
<span class="line"><span>④ 分布式数据库（TiDB）    ：数据切片 + 每片多副本，底层封装成&quot;一个库&quot;</span></span></code></pre></div><p><strong>最容易混的两个</strong>：</p><ul><li>② 主从 = <strong>同一份数据</strong>多副本（每台都是全量）</li><li>③ 分库 = <strong>不同数据</strong>分散（每台存一部分）</li></ul><table tabindex="0"><thead><tr><th>形态</th><th>数据是&quot;切&quot;还是&quot;复制&quot;</th><th>一致性</th><th>扩展方向</th></tr></thead><tbody><tr><td>① 单库</td><td>一份</td><td>强一致（DB 保证）</td><td>加应用实例（水平）</td></tr><tr><td>② 主从</td><td><strong>复制</strong>（全量副本）</td><td>最终一致（异步复制）</td><td><strong>读</strong>扩展</td></tr><tr><td>③ 分片</td><td><strong>切分</strong>（各存部分）</td><td>各片独立（跨片要分布式事务）</td><td>写 + 读扩展</td></tr><tr><td>④ TiDB</td><td>切分 + 副本</td><td>底层封装（对外像单库）</td><td>自动扩展</td></tr></tbody></table><hr><h2 id="二、场景1-多应用实例-单库" tabindex="-1">二、场景①：多应用实例 + 单库 <a class="header-anchor" href="#二、场景1-多应用实例-单库" aria-label="Permalink to &quot;二、场景①：多应用实例 + 单库&quot;">​</a></h2><p><strong>数据</strong>：一份，所有实例连同一个 MySQL。</p><p><strong>锁设计</strong>：</p><ul><li><strong>数据一致性 → DB 锁</strong>（行锁/乐观锁/原子 SQL）——共享 DB，行锁<strong>天然跨实例</strong>，不管几个应用实例都有效</li><li><strong>代码互斥 → Redis 锁</strong>——&quot;定时任务只跑一次&quot;这类<strong>与数据行无关</strong>的逻辑互斥，DB 管不了，用 Redis 锁（key 粒度决定并发度）</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>数据行 → DB 行锁（自动，跨实例）</span></span>
<span class="line"><span>代码段 → Redis 锁（自己加，跨实例）</span></span></code></pre></div><p><strong>核心认知</strong>：应用再多实例，只要共享 DB，数据一致就靠 DB；Redis 锁只补&quot;代码互斥&quot;这块。</p><hr><h2 id="三、场景2-主从复制-读写分离-最常见的部署形态" tabindex="-1">三、场景②：主从复制 / 读写分离（最常见的部署形态） <a class="header-anchor" href="#三、场景2-主从复制-读写分离-最常见的部署形态" aria-label="Permalink to &quot;三、场景②：主从复制 / 读写分离（最常见的部署形态）&quot;">​</a></h2><p><strong>架构</strong>：主库写、从库读，主库把 binlog 异步复制给从库。<strong>主从 = 同一份数据的多个全量副本</strong>。</p><h3 id="它解决什么-并发" tabindex="-1">它解决什么（并发） <a class="header-anchor" href="#它解决什么-并发" aria-label="Permalink to &quot;它解决什么（并发）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>读并发大 → 加从库（每台从库分担一部分读流量）→ 读水平扩展</span></span>
<span class="line"><span>写并发   → 瓶颈仍在主库（单点写）→ 主从不解决写扩展（要写扩展走分库）</span></span></code></pre></div><p><strong>写一致性还在主库</strong>：所有写都走主库，主库的行锁和单库场景一样管并发写——<strong>从库只读，没有写并发问题</strong>。</p><h3 id="真正的难点-复制延迟导致的一致问题" tabindex="-1">真正的难点：复制延迟导致的一致问题 <a class="header-anchor" href="#真正的难点-复制延迟导致的一致问题" aria-label="Permalink to &quot;真正的难点：复制延迟导致的一致问题&quot;">​</a></h3><p>主库写完，binlog 异步复制到从库——<strong>从库会暂时落后</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户下单 → 写主库成功 → 跳转订单页 → 读的是从库 → 可能还没复制到 → &quot;订单不存在&quot;？</span></span></code></pre></div><p><strong>主从是&quot;最终一致&quot;</strong>：从库迟早追上，但追上之前的窗口内，读到的是旧数据。</p><h3 id="解决策略-不是加锁-是复制与路由策略" tabindex="-1">解决策略（不是加锁！是复制与路由策略） <a class="header-anchor" href="#解决策略-不是加锁-是复制与路由策略" aria-label="Permalink to &quot;解决策略（不是加锁！是复制与路由策略）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>手段</th><th>做法</th><th>解决</th></tr></thead><tbody><tr><td><strong>半同步复制</strong></td><td>写主库时<strong>等至少一个从库 ACK 才返回成功</strong></td><td>缩小延迟窗口（从&quot;毫秒级不确定&quot;到&quot;至少一个从库确认&quot;）</td></tr><tr><td><strong>关键读走主库</strong></td><td>刚写过的数据（如自己的订单）路由到主库读</td><td>避免&quot;写后读不到自己写的数据&quot;</td></tr><tr><td><strong>读从库容忍延迟</strong></td><td>报表/列表这类可接受最终一致的读从库</td><td>榨干从库读能力</td></tr><tr><td><strong>复制延迟监控</strong></td><td>监控主从落后秒数，超阈值告警/切主读</td><td>别让延迟悄悄放大</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>写 → 主库（行锁保证写一致）→ 半同步等从库确认 → 返回成功</span></span>
<span class="line"><span>读关键数据 → 主库（要读到刚写的）</span></span>
<span class="line"><span>读可容忍数据 → 从库（可能旧几毫秒/秒，最终一致）</span></span></code></pre></div><p><strong>关键认知</strong>：主从的一致风险来自<strong>复制延迟</strong>（时序问题），<strong>不是并发写冲突</strong>（写都集中主库、按行锁串行）。所以&quot;锁&quot;在这里<strong>不解决一致</strong>——一致靠复制策略（半同步/路由）。<strong>这是主从和单库场景最大的思维差异：单库靠锁，主从靠复制策略</strong>。</p><h3 id="主从切换的坑-顺带" tabindex="-1">主从切换的坑（顺带） <a class="header-anchor" href="#主从切换的坑-顺带" aria-label="Permalink to &quot;主从切换的坑（顺带）&quot;">​</a></h3><p>主库宕机切从库时，可能丢&quot;还没复制过去的写&quot;——半同步 + GTID 定位可减少损失。<strong>主从是容灾 + 读扩展方案，不是数据零丢失方案</strong>（强零丢失得靠分布式 DB/同步复制）。</p><hr><h2 id="四、场景3-分库分表-数据切片" tabindex="-1">四、场景③：分库分表（数据切片） <a class="header-anchor" href="#四、场景3-分库分表-数据切片" aria-label="Permalink to &quot;四、场景③：分库分表（数据切片）&quot;">​</a></h2><p><strong>数据</strong>：按<strong>分片键</strong>（如 user_id、order_id）切到多个库，每库只存一部分。</p><h3 id="锁设计核心-让锁-局部化" tabindex="-1">锁设计核心：让锁&quot;局部化&quot; <a class="header-anchor" href="#锁设计核心-让锁-局部化" aria-label="Permalink to &quot;锁设计核心：让锁&quot;局部化&quot;&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一条数据 → 只在一个分片里 → 行锁在该分片自动生效（和单库一样）</span></span>
<span class="line"><span>跨分片的操作 → 一次改多个库的数据 → 需要分布式事务（代价大）</span></span></code></pre></div><p><strong>所以分片键设计是最高优先级的&quot;锁设计&quot;</strong>——让需要一起操作的数据落在同一分片：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>❌ 订单按 user_id 分片，但&quot;订单 + 订单明细 + 该订单库存扣减&quot;散在不同片 → 跨片事务</span></span>
<span class="line"><span>✅ 让&quot;一个订单的聚合&quot;同片 → 单分片内行锁局部有效，无需跨库协调</span></span></code></pre></div><h3 id="分片后的配套问题" tabindex="-1">分片后的配套问题 <a class="header-anchor" href="#分片后的配套问题" aria-label="Permalink to &quot;分片后的配套问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>方案</th></tr></thead><tbody><tr><td>自增主键失效（各片独立自增会撞）</td><td><strong>分布式 ID</strong>（雪花：时间戳+机器+序号）</td></tr><tr><td>跨分片事务</td><td>分布式事务（2PC/TCC/Saga，能避免就避免）</td></tr><tr><td>跨库无唯一约束</td><td>幂等表 / Redis 幂等记录</td></tr><tr><td>热点分片（某 key 特别热）</td><td>拆 key（加后缀分散）/ 本地缓存</td></tr></tbody></table><p><strong>判断准则</strong>：<strong>能局部锁就别跨节点</strong>——分片键设计的目标是让 90% 操作落在单片内（局部行锁），只有极少数跨片才付分布式事务的代价。</p><hr><h2 id="五、场景4-分布式数据库-tidb-cockroachdb-了解一下" tabindex="-1">五、场景④：分布式数据库（TiDB / CockroachDB，了解一下） <a class="header-anchor" href="#五、场景4-分布式数据库-tidb-cockroachdb-了解一下" aria-label="Permalink to &quot;五、场景④：分布式数据库（TiDB / CockroachDB，了解一下）&quot;">​</a></h2><p><strong>本质</strong>：分片（Region）+ 每片多副本（Raft 共识）+ 分布式事务（TiDB 用 Google Percolator 模型）——<strong>全部封装在存储层</strong>，对外是一个 MySQL 兼容的库。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你写：UPDATE stock SET stock=stock-1 WHERE id=1</span></span>
<span class="line"><span>底层：找到 id 所在 Region → 多副本 Raft 达成一致 → 行锁/MVCC 内部协调</span></span></code></pre></div><p><strong>对应用透明</strong>：行锁、事务隔离级别和单库一样，<strong>不需要你设计锁/分片/副本</strong>——数据库全包了。</p><p><strong>代价</strong>：引入运维复杂度（TiDB 集群本身要管）、强一致写有跨节点协调开销。适用：<strong>单库扛不住又不愿自己搞分库分表的团队</strong>。</p><hr><h2 id="六、对照总结-学透这张表就够了" tabindex="-1">六、对照总结（学透这张表就够了） <a class="header-anchor" href="#六、对照总结-学透这张表就够了" aria-label="Permalink to &quot;六、对照总结（学透这张表就够了）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>数据形态</th><th>写一致靠</th><th>读扩展</th><th>写扩展</th><th>你要&quot;设计&quot;的</th></tr></thead><tbody><tr><td>① 多实例单库</td><td>一份</td><td><strong>DB 行锁</strong></td><td>加实例</td><td>加实例（受单库上限）</td><td>Redis 锁管代码互斥</td></tr><tr><td>② 主从</td><td>全量多副本</td><td>主库行锁 + <strong>复制策略</strong></td><td><strong>加从库</strong></td><td>❌（主库单点）</td><td>半同步/读写路由/延迟监控</td></tr><tr><td>③ 分片</td><td>各存部分</td><td>片内行锁 + 跨片事务</td><td>加片</td><td>加片</td><td><strong>分片键</strong>/分布式ID/幂等</td></tr><tr><td>④ TiDB</td><td>切片+副本</td><td><strong>内部封装</strong></td><td>自动</td><td>自动</td><td>基本不用</td></tr></tbody></table><p><strong>贯穿主线一句话</strong>：<strong>能局部锁就别跨节点</strong>——单库靠 DB 行锁，主从靠复制策略（不是锁），分片靠分片键让锁局部化，分布式库靠底层封装。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/knowledge/service/concurrency-locks.html">并发锁应用</a> - 锁的粒度/阵营/具体 API</li><li><a href="/knowledge/service/distributed-basics.html">分布式基础</a> - 分布式事务/一致性概念</li><li><a href="/knowledge/service/java-high-concurrency.html">Java 高并发与高可用设计</a> - 架构视角</li></ul>`,52)])])}const u=a(e,[["render",d]]);export{c as __pageData,u as default};
